budget.value:
fun p =>
  have κ := p.L / p.μ;
  have G := 2 + p.ρ / 8 + p.ρ ^ 2 / 128;
  have C := fun x => ↑p.h * (↑p.l + ↑p.β * (64 + ↑p.d * Real.log x));
  if p.R ≤ p.ε then 0
  else
    if 64 * κ * G ≤ ↑↑p.n then
      have T := min ⌊κ⌋₊ ⌊Real.log (↑↑p.n / (64 * κ)) / Real.log G⌋₊;
      have q := 1 + 32 * p.ρ * p.M * p.R * G ^ T / p.μ;
      (65536 *
          ((↑p.τ * p.ρ * κ ^ 2 + C (2 * ↑↑p.n)) * (1 + Real.log (↑p.d * q)) + ↑p.τ * κ * Real.log (p.R / p.ε) +
            C (2 + ↑↑p.n * ↑p.d * p.R / (p.ε * q)) * (κ / ↑T * max (Real.log (2 * p.R / (p.ε * q))) 0))).toNNReal
    else p.τ * ↑⌈p.ρ * κ ^ 2 * Real.log (p.R ^ 2 / p.ε ^ 2)⌉₊

